using System;

namespace Civ_1_5_Remastered.Imaging.Typefaces
{
	public static class ClassicRomTypeface
	{
		private const int CharacterAltitude = 16;
		private const int CharacterBreadth = 8;
		private const int ColumnsPerScreen = 80;

		private const string EncodedGlyphPayload =
			"";

		private static readonly byte[] GlyphData = Convert.FromBase64String(EncodedGlyphPayload);

		public static void RenderCharacter(byte[] storage, int pitch, byte characterCode, int column, int row, byte foregroundHue, byte? backgroundHue)
		{
			int glyphOffset = characterCode * CharacterAltitude;
			int screenHorizontal = column * CharacterBreadth;
			int screenVertical = row * CharacterAltitude;

			for (int glyphRow = 0; glyphRow < CharacterAltitude; glyphRow++)
			{
				byte rowBits = GlyphData[glyphOffset + glyphRow];
				int targetOffset = ((screenVertical + glyphRow) * pitch) + screenHorizontal;

				for (int glyphColumn = 0; glyphColumn < CharacterBreadth; glyphColumn++)
				{
					if ((rowBits & (1 << (7 - glyphColumn))) != 0)
					{
						storage[targetOffset + glyphColumn] = foregroundHue;
					}
					else if (backgroundHue.HasValue)
					{
						storage[targetOffset + glyphColumn] = backgroundHue.Value;
					}
				}
			}
		}

		public static void RenderText(byte[] storage, int pitch, string text, int column, int row, byte foregroundHue, byte? backgroundHue)
		{
			for (int index = 0; index < text.Length; index++)
			{
				RenderCharacter(storage, pitch, (byte)text[index], column + index, row, foregroundHue, backgroundHue);
			}
		}

		public static void RenderCenteredText(byte[] storage, int pitch, string text, int row, byte foregroundHue, byte? backgroundHue)
		{
			int startColumn = (ColumnsPerScreen - text.Length) / 2;
			RenderText(storage, pitch, text, startColumn, row, foregroundHue, backgroundHue);
		}
	}
}
